insert:
QtObject {
id: p
property url popup_area_lower: "qrc:/assets/images/popup_area_center_2r_lower.png"
property url context_normal: "qrc:/assets/images/list_context_4s_no_separator_normal.png"
property url context_pressed: "qrc:/assets/images/list_context_4s_no_separator_pressed.png"
property url context_separator: "qrc:/assets/images/separator_context.png"
}
BorderImage {
id: centerImage
source: p.popup_area_lower
width: listArea.width
height: Math.max(0,listArea.height - cellHeight - separatorHeight + bottomMargin)
visible: filtered.count>0
border { top: 3; left: 3; right: 3; bottom: 3; }
}
Image {
id: footer
anchors {top: centerImage.bottom; right: centerImage.right;}
width: listArea.width
height: cellHeight + separatorHeight
source: p.popup_area_lower
}
Item {
id: listArea
anchors {top: menuList.top; right: menuList.right;}
width: cellWidth
height: Math.max(0,(cellHeight + separatorHeight) * visibleAreaCellCount - separatorHeight)
visible: menuList.visible && filtered.count>0
ListView{
id: list
anchors.fill: parent
model: filtered
delegate: delegate
highlightFollowsCurrentItem: false
boundsBehavior: Flickable.StopAtBounds
snapMode: ListView.SnapToItem
clip: true
focus: true
onModelChanged: {
list.currentIndex = -1
}
}
Item{
id:scrollArea
width:labelMargin
anchors {top: parent.top; bottom: parent.bottom; right: parent.right;}
SCmnScrollIndicator {
id: scroll
anchors {horizontalCenter: parent.horizontalCenter; top: parent.top; bottom: parent.bottom;}
flickable: list
}
}
}
Component {
id: delegate
Item {
height: (index===list.count-1)? cellHeight : (cellHeight + separatorHeight)
width: cellWidth
SCmnButton {
anchors { top: parent.top; left: parent.left; right: parent.right; }
height: cellHeight
loadComponent: Item {
anchors.fill: parent
Image {
anchors.fill: parent
source: p.context_normal
}
SCmnLabel {
anchors { fill: parent; leftMargin: labelMargin; rightMargin: labelMargin; }
verticalAlignment: Text.AlignVCenter
text: menu_text
font.pixelSize: viewstyle.textsize.L
font.weight: Font.Light
clip: true
maximumLineCount: 2
elide: Text.ElideRight
wrapMode: Text.WordWrap
}
}
pressedComponent: Item {
anchors.fill: parent
Image {
anchors.fill: parent
source: p.context_pressed
}
SCmnLabel {
anchors { fill: parent; leftMargin: labelMargin; rightMargin: labelMargin; }
verticalAlignment: Text.AlignVCenter
text: menu_text
font.pixelSize: viewstyle.textsize.L
font.weight: Font.Light
clip: true
maximumLineCount: 2
elide: Text.ElideRight
wrapMode: Text.WordWrap
}
}
onPressed: {
list.currentIndex = index
}
onReleased: {
list.currentIndex = -1
}
onClicked: {
menuList.clicked(menu_id)
}
}
Image {
anchors { bottom: parent.bottom; horizontalCenter: parent.horizontalCenter }
visible: (index===list.count-1)? false : true
height: separatorHeight
source: p.context_separator
}
}
}
ListModel { id: filtered }
function bookmarkKind(text) {
return PathLabels.kind(text,qsTr("020031"))
}
function rebuild() {
filtered.clear()
for(var i=0;i<sourceRows.count;i++) {
var row=sourceRows.objectAt(i)
if(!row)continue
var kind=bookmarkKind(row.label)
if(kind !== 2)filtered.append({menu_text:kind === 1 ? "Audio Path" : row.label,menu_id:row.menuId})
}
}
Timer { id: rebuildTimer; interval: 0; onTriggered: menuList.rebuild() }
Instantiator {
id: sourceRows
model: menuList.titleList
delegate: QtObject {
property string label: menu_text
property int menuId: menu_id
onLabelChanged: rebuildTimer.restart()
onMenuIdChanged: rebuildTimer.restart()
}
onObjectAdded: rebuildTimer.restart()
onObjectRemoved: rebuildTimer.restart()
}
}
